import { Page, Locator } from '@playwright/test';

/**
 * Blinkit Customer Login Page
 * URL: https://blinkit-demo-qa.vercel.app
 *
 * Generated by /explore from LIVE DOM (2026-08-24) for Epic SCRUM-722.
 *
 * Every locator below was confirmed against the accessibility snapshot and/or
 * the served HTML — none are invented. The element ids (#firstName, #loginBtn,
 * ...) are author-written and static, not framework-generated, so they are
 * stable locator targets.
 *
 * SCOPE: the login page only. A successful login navigates to
 * blinkit-products.html — a DIFFERENT URL, therefore out of scope for this POM
 * (AH Rule 27). Assert the navigation, not the destination's contents.
 */
export class BlinkitLoginPage {
  readonly page: Page;

  static readonly URL = 'https://blinkit-demo-qa.vercel.app';

  // --- Form Fields ---
  readonly firstNameInput: Locator;
  readonly lastNameInput: Locator;
  readonly mobileInput: Locator;

  // --- Buttons ---
  readonly loginButton: Locator;
  readonly createAccountButton: Locator;

  // --- Links ---
  readonly forgotPasswordLink: Locator;

  // --- Validation Messages (hidden until submit — always waitFor before asserting) ---
  readonly firstNameError: Locator;
  readonly lastNameError: Locator;
  readonly mobileError: Locator;

  // --- Toast (shared channel — forgot-password AND login success both write here) ---
  readonly toast: Locator;

  // --- Static Text ---
  readonly welcomeHeading: Locator;
  readonly countryCodePrefix: Locator;

  constructor(page: Page) {
    this.page = page;

    // --- Form Fields ---
    this.firstNameInput = page.getByRole('textbox', { name: 'First Name' });
    this.lastNameInput = page.getByRole('textbox', { name: 'Last Name' });
    // #mobile carries maxlength=10 and strips non-digits on every input event.
    this.mobileInput = page.getByRole('textbox', { name: 'Mobile Number' });

    // --- Buttons ---
    // #loginBtn is type=submit and is ALWAYS enabled — validation happens on
    // submit, never by disabling the control.
    this.loginButton = page.getByRole('button', { name: 'Login' });
    this.createAccountButton = page.getByRole('button', { name: 'Create New Account' });

    // --- Links ---
    // href="#" — activating this does NOT change the URL.
    this.forgotPasswordLink = page.getByRole('link', { name: 'Forgot Password?' });

    // --- Validation Messages ---
    // Author-written static ids. These nodes exist in the DOM at all times but
    // are display:none until submit, so they are absent from the at-rest
    // accessibility snapshot. Use toBeVisible(), never a bare count check.
    this.firstNameError = page.locator('#firstNameErr');
    this.lastNameError = page.locator('#lastNameErr');
    this.mobileError = page.locator('#mobileErr');

    // --- Toast ---
    // Single #toast node reused by both flows, auto-dismissed after 3000ms.
    // Assert its text promptly; a late assertion races the dismissal.
    this.toast = page.locator('#toast');

    // --- Static Text ---
    this.welcomeHeading = page.getByRole('heading', { name: 'Welcome back' });
    this.countryCodePrefix = page.getByText('+91', { exact: true });
  }

  // --- Navigation ---
  async navigate() {
    await this.page.goto(BlinkitLoginPage.URL);
  }

  // --- Actions ---
  async fillCredentials(firstName: string, lastName: string, mobile: string) {
    await this.firstNameInput.fill(firstName);
    await this.lastNameInput.fill(lastName);
    await this.mobileInput.fill(mobile);
  }

  async login(firstName: string, lastName: string, mobile: string) {
    await this.fillCredentials(firstName, lastName, mobile);
    await this.loginButton.click();
  }

  async submitEmpty() {
    await this.loginButton.click();
  }

  async clickForgotPassword() {
    await this.forgotPasswordLink.click();
  }

  async clickCreateAccount() {
    await this.createAccountButton.click();
  }

  // --- Reads ---
  async toastText(): Promise<string> {
    await this.toast.waitFor({ state: 'visible' });
    return (await this.toast.textContent())?.trim() ?? '';
  }

  /**
   * Value actually held by #mobile after the input handler has run.
   * Use this to check truncation/filtering rather than asserting on what was typed.
   */
  async mobileValue(): Promise<string> {
    return this.mobileInput.inputValue();
  }
}
